"""Cron job that aggregates the previous day's fuzzer statistics and loads
  them into a BigQuery data warehouse."""

import argparse
import datetime
import io
import json

from googleapiclient.errors import HttpError
from googleapiclient.http import MediaIoBaseUpload

from clusterfuzz._internal.base import utils
from clusterfuzz._internal.google_cloud_utils import big_query
from clusterfuzz._internal.metrics import logs

# BigQuery dataset and table that the aggregated stats are written to.
DATASET_ID = 'fuzzer_stats'
TABLE_ID = 'daily_stats'

# Schema for the |daily_stats| table. The table is partitioned by day on the
# |date| field (see _create_table_if_needed).
DAILY_STATS_SCHEMA = {
    'fields': [
        {
            'name': 'fuzzer_name',
            'type': 'STRING',
            'mode': 'NULLABLE',
        },
        {
            'name': 'date',
            'type': 'DATE',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcases_executed',
            'type': 'INTEGER',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcase_execution_duration',
            'type': 'FLOAT',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcases_generated',
            'type': 'INTEGER',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcase_generation_duration',
            'type': 'FLOAT',
            'mode': 'NULLABLE',
        },
        {
            'name': 'fuzzing_duration',
            'type': 'FLOAT',
            'mode': 'NULLABLE',
        },
    ],
}

# Fields, in schema order, that make up each uploaded record.
_RECORD_FIELDS = [field['name'] for field in DAILY_STATS_SCHEMA['fields']]

# Query used to aggregate the previous day's per-fuzzer statistics. The target
# date is substituted into both the projected |date| column and the filter on
# the raw event timestamp.
QUERY_FORMAT = """\
SELECT
  fuzzer AS fuzzer_name,
  '{date}' AS date,
  SUM(testcases_executed) AS testcases_executed,
  SUM(testcase_execution_duration) AS testcase_execution_duration,
  SUM(testcases_generated) AS testcases_generated,
  SUM(testcase_generation_duration) AS testcase_generation_duration,
  SUM(fuzzing_duration) AS fuzzing_duration
FROM `{project_id}.fuzzer_stats.TestcaseRun`
WHERE DATE(TIMESTAMP_SECONDS(CAST(timestamp AS INT64))) = '{date}'
GROUP BY fuzzer_name
"""


def _utc_now():
  """Return datetime.datetime.utcnow(). Wrapped for testing."""
  return datetime.datetime.utcnow()


def _valid_date(value):
  """argparse type that validates a YYYY-MM-DD date string."""
  try:
    return datetime.datetime.strptime(value, '%Y-%m-%d').date()
  except ValueError as e:
    raise argparse.ArgumentTypeError(
        f'Invalid date "{value}", expected format YYYY-MM-DD.') from e


def _parse_args(args):
  """Parse the command-line arguments for the cron job."""
  parser = argparse.ArgumentParser(
      description='Aggregate the previous day\'s fuzzer stats into BigQuery.')
  parser.add_argument(
      '--non-dry-run',
      action='store_true',
      help='If set, actually create the dataset/table and load the data.')
  parser.add_argument(
      '--date',
      type=_valid_date,
      default=None,
      help='Target date (YYYY-MM-DD) to aggregate. Defaults to yesterday.')
  return parser.parse_args(args)


def _create_dataset_if_needed(bigquery, project_id, dataset_id):
  """Create the dataset, ignoring 409 (already exists) errors."""
  dataset_body = {
      'datasetReference': {
          'projectId': project_id,
          'datasetId': dataset_id,
      },
  }
  try:
    bigquery.datasets().insert(
        projectId=project_id, body=dataset_body).execute()
  except HttpError as e:
    if e.resp.status == 409:
      logs.info(f'Dataset {dataset_id} already exists.')
      return
    raise


def _create_table_if_needed(bigquery, project_id, dataset_id, table_id):
  """Create the daily stats table, ignoring 409 (already exists) errors."""
  table_body = {
      'tableReference': {
          'projectId': project_id,
          'datasetId': dataset_id,
          'tableId': table_id,
      },
      'timePartitioning': {
          'type': 'DAY',
          'field': 'date',
      },
      'schema': DAILY_STATS_SCHEMA,
  }
  try:
    bigquery.tables().insert(
        projectId=project_id, datasetId=dataset_id,
        body=table_body).execute()
  except HttpError as e:
    if e.resp.status == 409:
      logs.info(f'Table {table_id} already exists.')
      return
    raise


def _query_stats(bigquery, project_id, date_string):
  """Query the previous day's aggregated fuzzer stats."""
  query = QUERY_FORMAT.format(project_id=project_id, date=date_string)
  body = {
      'query': query,
      'useLegacySql': False,
  }
  result = bigquery.jobs().query(projectId=project_id, body=body).execute()
  return _rows_from_result(result)


def _rows_from_result(result):
  """Normalize a BigQuery query response into a list of dict rows."""
  rows = result.get('rows', [])
  if not rows:
    return []

  # Raw REST response uses the {'f': [{'v': ...}]} row format alongside a
  # schema. Use the shared helper to convert those into plain dicts.
  if isinstance(rows[0], dict) and 'f' in rows[0] and 'schema' in result:
    return big_query.convert(result)

  return rows


def _build_upload_data(rows, date_string):
  """Build newline-delimited JSON for the load job from the query rows."""
  lines = []
  for row in rows:
    record = {field: row.get(field) for field in _RECORD_FIELDS}
    # The partition/date is always the target date being aggregated.
    if record.get('date') is None:
      record['date'] = date_string
    lines.append(json.dumps(record))

  return '\n'.join(lines)


def _load_data(bigquery, project_id, dataset_id, table_id, partition_suffix,
               data):
  """Create a load job that uploads |data| into the daily partition."""
  job_body = {
      'configuration': {
          'load': {
              'destinationTable': {
                  'projectId': project_id,
                  'datasetId': dataset_id,
                  'tableId': f'{table_id}${partition_suffix}',
              },
              'sourceFormat': 'NEWLINE_DELIMITED_JSON',
              'writeDisposition': 'WRITE_TRUNCATE',
              'schema': DAILY_STATS_SCHEMA,
          },
      },
  }

  media_body = MediaIoBaseUpload(
      io.BytesIO(data.encode('utf-8')),
      mimetype='application/octet-stream',
      resumable=True)

  logs.info('Uploading aggregated fuzzer stats to BigQuery.', job_body=job_body)
  bigquery.jobs().insert(
      projectId=project_id, body=job_body, media_body=media_body).execute()


